/*
 * Example demonstrating how to write data and force a specific range
 * to be synchronized to disk using sync_file_range.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <string.h>
#include <errno.h>

int main() {
    const char *filepath = "./temp_data_sync.dat";
    const char *data = "This is the data segment that must be synchronized.";
    off_t offset = 0;
    off_t nbytes = strlen(data);
    int fd;

    fd = open(filepath, O_CREAT | O_WRONLY, 0666);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (write(fd, data, nbytes) != nbytes) {
        perror("write");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Data written to file. Initiating range synchronization...\n");

    /* 
     * Flags: Initiate write (WRITE) and wait for completion (WAIT_AFTER).
     * This ensures the segment is flushed and confirmed complete.
     */
    unsigned int flags = SYNC_FILE_RANGE_WRITE | SYNC_FILE_RANGE_WAIT_AFTER;

    if (sync_file_range(fd, offset, nbytes, flags) == -1) {
        if (errno == ENOSYS) {
             fprintf(stderr, "Error: sync_file_range not supported on this system/filesystem.\n");
        } else {
             perror("sync_file_range");
        }
        close(fd);
        unlink(filepath);
        return EXIT_FAILURE;
    }

    printf("Range synchronization successful for %ld bytes starting at offset %ld.\n", (long)nbytes, (long)offset);

    close(fd);
    unlink(filepath);
    return EXIT_SUCCESS;
}
